public bool HasUniqueSubstringOfLengthK(string s, int k)
{
    if (k > s.Length)
        return false;

    var counts = new Dictionary<char, int>();
    int left = 0;

    for (int right = 0; right < s.Length; right++)
    {
        counts[s[right]] = counts.GetValueOrDefault(s[right]) + 1;

        if (right - left + 1 > k)
        {
            counts[s[left]]--;
            if (counts[s[left]] == 0)
                counts.Remove(s[left]);
            left++;
        }

        if (right - left + 1 == k && counts.Count == k)
            return true;
    }

    return false;
}

